[{"order":1,"type":"heading","text":"Material-UI: A Comprehensive Guide to React's Component Library"},{"order":2,"type":"paragraph","text":"Material-UI (now known as MUI) is a popular React UI framework that provides a set of pre-designed, customizable components for building modern web applications. It implements Google's Material Design principles, offering a consistent and visually appealing user interface. This tutorial will guide you through the fundamentals of using Material-UI, from installation to advanced customization."},{"order":3,"type":"heading","text":"1. Setting Up Your React Project"},{"order":4,"type":"paragraph","text":"Before diving into Material-UI, you'll need a React project. If you don't have one already, create a new project using Create React App:"},{"order":5,"type":"code","text":"npx create-react-app my-mui-app
cd my-mui-app"},{"order":6,"type":"heading","text":"2. Installing Material-UI (MUI)"},{"order":7,"type":"paragraph","text":"Install the core Material-UI packages using npm or yarn:"},{"order":8,"type":"code","text":"npm install @mui/material @emotion/react @emotion/styled
# or
yarn add @mui/material @emotion/react @emotion/styled"},{"order":9,"type":"paragraph","text":"Explanation of packages:"},{"order":10,"type":"bullet_point","text":"@mui/material: Contains the core Material-UI components."},{"order":11,"type":"bullet_point","text":"@emotion/react: A peer dependency required by Material-UI for styling."},{"order":12,"type":"bullet_point","text":"@emotion/styled: Another peer dependency for styling components."},{"order":13,"type":"heading","text":"3. Using Your First Material-UI Component"},{"order":14,"type":"paragraph","text":"Let's start by using a simple Button component. Open `src/App.js` and modify it as follows:"},{"order":15,"type":"code","text":"import React from 'react';
import Button from '@mui/material/Button';

function App() {
  return (
    <div className="App">
      <Button variant="contained" color="primary">
        Hello Material-UI
      </Button>
    </div>
  );
}

export default App;"},{"order":16,"type":"paragraph","text":"Run your application (`npm start` or `yarn start`), and you should see a Material-UI button on the screen."},{"order":17,"type":"heading","text":"4. Understanding Component Variants and Props"},{"order":18,"type":"paragraph","text":"Material-UI components are highly customizable using props. The `Button` component, for example, has several variants:"},{"order":19,"type":"bullet_point","text":"`contained`: A solid button with a background color."},{"order":20,"type":"bullet_point","text":"`outlined`: A button with a border."},{"order":21,"type":"bullet_point","text":"`text`: A button with no background or border (only text)."},{"order":22,"type":"paragraph","text":"It also accepts color props:"},{"order":23,"type":"bullet_point","text":"`primary`: Uses the primary color from your theme."},{"order":24,"type":"bullet_point","text":"`secondary`: Uses the secondary color from your theme."},{"order":25,"type":"bullet_point","text":"`error`:  Uses the error color from your theme."},{"order":26,"type":"bullet_point","text":"`warning`: Uses the warning color from your theme."},{"order":27,"type":"bullet_point","text":"`info`: Uses the info color from your theme."},{"order":28,"type":"bullet_point","text":"`success`: Uses the success color from your theme."},{"order":29,"type":"bullet_point","text":"`default`: The default color."},{"order":30,"type":"paragraph","text":"Example:"},{"order":31,"type":"code","text":"<Button variant="outlined" color="secondary">Outlined Button</Button>"},{"order":32,"type":"heading","text":"5. Theming and Customization"},{"order":33,"type":"paragraph","text":"Material-UI allows you to customize the look and feel of your application using themes. You can modify colors, typography, spacing, and more.  Create a `theme.js` file in your `src` directory:"},{"order":34,"type":"code","text":"// src/theme.js
import { createTheme } from '@mui/material/styles';

const theme = createTheme({
  palette: {
    primary: {
      main: '#2196f3', // Blue
    },
    secondary: {
      main: '#f50057', // Pink
    },
  },
});

export default theme;"},{"order":35,"type":"paragraph","text":"Now, wrap your application with the `ThemeProvider` component in `App.js`:"},{"order":36,"type":"code","text":"import React from 'react';
import Button from '@mui/material/Button';
import { ThemeProvider } from '@mui/material/styles';
import theme from './theme';

function App() {
  return (
    <ThemeProvider theme={theme}>
      <div className="App">
        <Button variant="contained" color="primary">
          Hello Material-UI
        </Button>
      </div>
    </ThemeProvider>
  );
}

export default App;"},{"order":37,"type":"paragraph","text":"The button's primary color will now be blue, as defined in your theme."},{"order":38,"type":"heading","text":"6. Layout Components: Grid and Box"},{"order":39,"type":"paragraph","text":"Material-UI provides layout components like `Grid` and `Box` to structure your application's content."},{"order":40,"type":"subheading","text":"Grid"},{"order":41,"type":"paragraph","text":"The `Grid` component is based on a 12-column grid system.  You can define how many columns each item should occupy on different screen sizes (xs, sm, md, lg, xl)."},{"order":42,"type":"code","text":"import Grid from '@mui/material/Grid';

function App() {
  return (
    <Grid container spacing={2}>
      <Grid item xs={12} md={6}>
        <Button variant="contained">Item 1</Button>
      </Grid>
      <Grid item xs={12} md={6}>
        <Button variant="contained">Item 2</Button>
      </Grid>
    </Grid>
  );
}"},{"order":43,"type":"paragraph","text":"In this example, each button will take up the full width on extra small screens (xs=12) and half the width on medium screens and larger (md=6)."},{"order":44,"type":"subheading","text":"Box"},{"order":45,"type":"paragraph","text":"The `Box` component is a versatile container that allows you to apply styling using CSS shorthand properties. It's a replacement for `div` with built-in styling capabilities."},{"order":46,"type":"code","text":"import Box from '@mui/material/Box';

function App() {
  return (
    <Box sx={{
      width: 300,
      height: 300,
      backgroundColor: 'primary.main',
      color: 'white',
      padding: 2,
    }}>
      This is a Box component.
    </Box>
  );
}"},{"order":47,"type":"paragraph","text":"The `sx` prop allows you to apply CSS styles directly to the `Box` component.  You can use theme variables (like `primary.main`) for consistent styling."},{"order":48,"type":"heading","text":"7. Working with Text Fields"},{"order":49,"type":"paragraph","text":"Material-UI provides a `TextField` component for handling user input. Here's a basic example:"},{"order":50,"type":"code","text":"import TextField from '@mui/material/TextField';

function App() {
  const [value, setValue] = React.useState('');

  const handleChange = (event) => {
    setValue(event.target.value);
  };

  return (
    <TextField
      id="outlined-basic"
      label="Enter Text"
      variant="outlined"
      value={value}
      onChange={handleChange}
    />
  );
}"},{"order":51,"type":"paragraph","text":"This code creates a controlled `TextField` component, where the value is managed by the React state. The `onChange` handler updates the state whenever the user types something."},{"order":52,"type":"heading","text":"8. Styling with makeStyles (Legacy) and styled-components (Modern)"},{"order":53,"type":"paragraph","text":"Material-UI offers several ways to style components.  The older approach used `makeStyles`, but the recommended approach now is to use `styled-components`."},{"order":54,"type":"subheading","text":"`styled-components` (Recommended)"},{"order":55,"type":"paragraph","text":"This approach uses the `@emotion/styled` package that you installed earlier. It allows you to create styled components with CSS-in-JS."},{"order":56,"type":"code","text":"import { styled } from '@mui/material/styles';
import Button from '@mui/material/Button';

const MyButton = styled(Button)({
  background: 'linear-gradient(45deg, #FE6B8B 30%, #FF8E53 90%)',
  border: 0,
  borderRadius: 3,
  boxShadow: '0 3px 5px 2px rgba(255, 105, 135, .3)',
  color: 'white',
  height: 48,
  padding: '0 30px',
});

function App() {
  return <MyButton>Styled Button</MyButton>;
}"},{"order":57,"type":"paragraph","text":"This creates a new component `MyButton` that extends the Material-UI `Button` component with custom styles."},{"order":58,"type":"heading","text":"9. Conclusion"},{"order":59,"type":"paragraph","text":"This tutorial has covered the basics of using Material-UI in your React projects. You've learned how to install the library, use basic components, customize the theme, and style components. Material-UI offers a vast collection of components and features, so explore the official documentation to discover more advanced capabilities and build sophisticated user interfaces."}]
